G14a.code:
Module[{n, edges, eset, cliqueQ, cl, vv, ee, tt, qq, bd, d1, d2, inv, s1, s2, r1, r2},
n = 14; edges = {{1,5},{1,6},{1,9},{1,11},{1,13},{1,14},{2,6},{2,8},{2,9},{2,11},{2,13},{2,14},{3,7},{3,8},{3,10},{3,13},{3,14},{4,7},{4,10},{4,11},{4,13},{4,14},{5,9},{5,10},{5,12},{5,14},{6,10},{6,11},{6,12},{6,13},{7,8},{7,11},{7,12},{7,13},{8,9},{8,12},{8,14},{9,12},{9,13},{10,12},{10,13},{10,14},{11,12},{11,14}}; eset = Association[(# -> True) & /@ edges];
cliqueQ[s_] := AllTrue[Subsets[s, {2}], KeyExistsQ[eset, #] &];
cl[k_] := Select[Subsets[Range[n], {k}], cliqueQ];
vv = cl[1]; ee = cl[2]; tt = cl[3]; qq = cl[4];
bd[hi_, lo_] := Module[{idx = AssociationThread[lo -> Range[Length[lo]]]},
  Normal[SparseArray[Flatten[Table[{idx[Delete[hi[[j]], t]], j} -> (-1)^(t - 1), {j, Length[hi]}, {t, Length[hi[[j]]]}], 1], {Length[lo], Length[hi]}]]];
d1 = bd[ee, vv]; d2 = bd[tt, ee];
inv[m_] := Module[{s = SmithDecomposition[m][[2]]}, DeleteCases[Abs[Diagonal[s]], 0]];
s1 = inv[d1]; s2 = inv[d2];
r1 = Length[s1]; r2 = Length[s2];
{"n"->Length[vv], "aristas"->Length[ee], "triangulos"->Length[tt], "K4"->Length[qq],
 "d1.d2 cero"->(Max[Abs[d1.d2]] == 0),
 "b0"->Length[vv]-r1, "b1"->Length[ee]-r1-r2, "b2"->Length[tt]-r2,
 "torsion H0"->Select[s1,#>1&], "torsion H1"->Select[s2,#>1&], "SNF d2"->Tally[s2]}]

